import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <algorithm>
#include <cute/tensor.hpp>
using namespace cute;
extern __shared__ float smem_raw[];
// THREAD_TILE is a compile-time register-blocking factor: each thread
// computes a THREAD_TILE x THREAD_TILE block of output pixels, reusing
// each weight value loaded from shared memory across THREAD_TILE*THREAD_TILE
// accumulators (register blocking) instead of only 2x2 as before.
template<int THREAD_TILE>
__global__ void conv2d_tiled_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout,
    int TILE_H, int TILE_W, int IH_tile, int IW_tile, int COUT_TILE)
{
  int n = blockIdx.z;
  int tile_oh0 = blockIdx.y * TILE_H;
  int tile_ow0 = blockIdx.x * TILE_W;
  int half_w = TILE_W / THREAD_TILE;
  int half_h = TILE_H / THREAD_TILE;
  int tx = threadIdx.x % half_w;
  int ty = threadIdx.x / half_w;
  int oh0 = tile_oh0 + ty * THREAD_TILE;
  int ow0 = tile_ow0 + tx * THREAD_TILE;
  int ih0 = tile_oh0 * stride - padding;
  int iw0 = tile_ow0 * stride - padding;
  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * (int64_t)Cin * H * Win),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{}));
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * (int64_t)Cout * Hout * Wout),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  // Shared memory tensor for the input tile: (Cin, IH_tile, IW_tile)
  auto sX = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(Cin, IH_tile, IW_tile),
      make_stride(IH_tile * IW_tile, IW_tile, Int<1>{}));
  // Shared memory tensor for a chunk of weights: (COUT_TILE, Cin, K, K)
  // The Cout dimension is tiled so the weight staging buffer fits within
  // the device's dynamic shared memory budget regardless of Cout.
  float* smem_W = smem_raw + (size_t)Cin * IH_tile * IW_tile;
  auto sW = make_tensor(
      make_smem_ptr(smem_W),
      make_shape(COUT_TILE, Cin, K, K),
      make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, Int<1>{}));
  int nthreads = blockDim.x;
  int tile_elems = Cin * IH_tile * IW_tile;
  int hw_tile = IH_tile * IW_tile;
  for (int idx = threadIdx.x; idx < tile_elems; idx += nthreads) {
    int c   = idx / hw_tile;
    int rem = idx - c * hw_tile;
    int r   = rem / IW_tile;
    int cc  = rem - r * IW_tile;
    int ih = ih0 + r;
    int iw = iw0 + cc;
    float val = 0.0f;
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      val = mX(c, ih, iw);
    }
    sX(c, r, cc) = val;
  }
  __syncthreads();
  int oh[THREAD_TILE];
  int ow[THREAD_TILE];
  #pragma unroll
  for (int i = 0; i < THREAD_TILE; ++i) { oh[i] = oh0 + i; ow[i] = ow0 + i; }
  bool active[THREAD_TILE][THREAD_TILE];
  bool any_active = false;
  #pragma unroll
  for (int i = 0; i < THREAD_TILE; ++i) {
    #pragma unroll
    for (int j = 0; j < THREAD_TILE; ++j) {
      bool a = (oh[i] < Hout && ow[j] < Wout);
      active[i][j] = a;
      any_active = any_active || a;
    }
  }
  int local_h0 = ty * THREAD_TILE * stride;
  int local_w0 = tx * THREAD_TILE * stride;
  int per_chunk_elems = Cin * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COUT_TILE) {
    int this_tile = min(COUT_TILE, Cout - co0);
    int wchunk_total = this_tile * per_chunk_elems;
    for (int idx = threadIdx.x; idx < wchunk_total; idx += nthreads) {
      smem_W[idx] = Wt[(int64_t)co0 * per_chunk_elems + idx];
    }
    __syncthreads();
    if (any_active) {
      for (int co_local = 0; co_local < this_tile; co_local += 4) {
        int co_local1 = co_local;
        bool has2 = (co_local + 1) < this_tile;
        bool has3 = (co_local + 2) < this_tile;
        bool has4 = (co_local + 3) < this_tile;
        int co_local2 = has2 ? co_local + 1 : co_local1;
        int co_local3 = has3 ? co_local + 2 : co_local1;
        int co_local4 = has4 ? co_local + 3 : co_local1;
        int co1 = co0 + co_local1;
        int co2 = co0 + co_local2;
        int co3 = co0 + co_local3;
        int co4 = co0 + co_local4;
        float bias_val1 = (Bias != nullptr) ? Bias[co1] : 0.0f;
        float bias_val2 = (Bias != nullptr) ? Bias[co2] : 0.0f;
        float bias_val3 = (Bias != nullptr) ? Bias[co3] : 0.0f;
        float bias_val4 = (Bias != nullptr) ? Bias[co4] : 0.0f;
        float acc1[THREAD_TILE][THREAD_TILE];
        float acc2[THREAD_TILE][THREAD_TILE];
        float acc3[THREAD_TILE][THREAD_TILE];
        float acc4[THREAD_TILE][THREAD_TILE];
        #pragma unroll
        for (int i = 0; i < THREAD_TILE; ++i) {
          #pragma unroll
          for (int j = 0; j < THREAD_TILE; ++j) {
            acc1[i][j] = bias_val1;
            acc2[i][j] = bias_val2;
            acc3[i][j] = bias_val3;
            acc4[i][j] = bias_val4;
          }
        }
        for (int ci = 0; ci < Cin; ++ci) {
          for (int kh = 0; kh < K; ++kh) {
            for (int kw = 0; kw < K; ++kw) {
              float wv1 = sW(co_local1, ci, kh, kw);
              float wv2 = has2 ? sW(co_local2, ci, kh, kw) : 0.0f;
              float wv3 = has3 ? sW(co_local3, ci, kh, kw) : 0.0f;
              float wv4 = has4 ? sW(co_local4, ci, kh, kw) : 0.0f;
              #pragma unroll
              for (int i = 0; i < THREAD_TILE; ++i) {
                int r = local_h0 + kh + i * stride;
                #pragma unroll
                for (int j = 0; j < THREAD_TILE; ++j) {
                  int c = local_w0 + kw + j * stride;
                  // Load the reusable input value once and reuse it across
                  // four output-channel accumulators, quartering the number
                  // of shared-memory reads of the input tile relative to
                  // computing one output channel at a time (improved reuse
                  // of the staged input tile across more output channels).
                  float xv = sX(ci, r, c);
                  acc1[i][j] += xv * wv1;
                  if (has2) acc2[i][j] += xv * wv2;
                  if (has3) acc3[i][j] += xv * wv3;
                  if (has4) acc4[i][j] += xv * wv4;
                }
              }
            }
          }
        }
        #pragma unroll
        for (int i = 0; i < THREAD_TILE; ++i) {
          #pragma unroll
          for (int j = 0; j < THREAD_TILE; ++j) {
            if (active[i][j]) {
              mY(co1, oh[i], ow[j]) = acc1[i][j];
              if (has2) mY(co2, oh[i], ow[j]) = acc2[i][j];
              if (has3) mY(co3, oh[i], ow[j]) = acc3[i][j];
              if (has4) mY(co4, oh[i], ow[j]) = acc4[i][j];
            }
          }
        }
      }
    }
    __syncthreads();
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  // Query device shared memory capacity to pick tile size
  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  if (max_smem_optin <= 0) {
    max_smem_optin = 48 * 1024; // conservative fallback
  }
  auto compute_input_bytes = [&](int tile) -> size_t {
    int ih_tile = (tile - 1) * stride + (int)K;
    int iw_tile = (tile - 1) * stride + (int)K;
    return (size_t)Cin * ih_tile * iw_tile * sizeof(float);
  };
  size_t per_channel_weight_bytes = (size_t)Cin * K * K * sizeof(float);
  auto compute_cout_tile = [&](size_t input_bytes, size_t budget) -> int {
    if (budget <= input_bytes) return 0;
    size_t remaining = budget - input_bytes;
    int ct = (int)(remaining / per_channel_weight_bytes);
    ct = std::max(0, std::min(ct, (int)Cout));
    return ct;
  };
  // Each resident block's shared-memory footprint (input tile + staged
  // weight chunk) directly determines how many blocks can be resident
  // per SM. Profiling shows theoretical occupancy is only 8.3%, driven
  // purely by the shared-memory reservation per block (not registers or
  // thread count), with an estimated ~92% speedup available by raising
  // the number of warps per scheduler. To attack this directly, search
  // progressively looser shared-memory budgets that target more
  // resident blocks per SM: first try to fit within 1/4 of the opt-in
  // shared-memory budget (aiming for ~4 resident blocks/SM), then 1/2
  // (~2 resident blocks/SM), and finally the full budget (previous
  // behavior, guaranteeing a valid configuration is always found).
  int candidate_tiles[4] = {16, 8, 4, 2};
  int occupancy_divisors[3] = {4, 2, 1};
  int TILE = 0;
  size_t input_bytes = 0;
  int cout_tile = 0;
  for (int div : occupancy_divisors) {
    size_t smem_budget = (size_t)max_smem_optin / div;
    for (int t : candidate_tiles) {
      size_t ib = compute_input_bytes(t);
      int ct = compute_cout_tile(ib, smem_budget);
      if (ct > 0) {
        TILE = t;
        input_bytes = ib;
        cout_tile = ct;
        break;
      }
    }
    if (cout_tile > 0) break;
  }
  TORCH_CHECK(cout_tile > 0,
      "Unable to fit even a single output channel's weights into the shared "
      "memory budget (", max_smem_optin, " bytes) alongside an input tile of ",
      input_bytes, " bytes");
  size_t smem_bytes = input_bytes + (size_t)cout_tile * per_channel_weight_bytes;
  TORCH_CHECK(smem_bytes <= (size_t)max_smem_optin,
      "Computed shared memory ", smem_bytes,
      " still exceeds device limit ", max_smem_optin);
  int IH_tile = (TILE - 1) * stride + (int)K;
  int IW_tile = (TILE - 1) * stride + (int)K;
  // Register blocking factor: use 4x4 per-thread output tiles when TILE
  // is divisible by 4 (reduces shared-memory reads per FMA by reusing
  // each loaded weight across 16 accumulators instead of 4), otherwise
  // fall back to 2x2.
  // Choose THREAD_TILE to maximize active threads per block. Because the
  // shared-memory footprint of this kernel (input tile + weight chunk)
  // already restricts residency to a single resident block per SM (as
  // confirmed by profiling: occupancy is shared-memory bound, not
  // register bound), the dominant lever left to raise achieved occupancy
  // is the number of cooperative threads actually launched inside that
  // one resident block. Prefer the smallest THREAD_TILE (i.e. the
  // largest blockDim) that still fits within the hardware per-block
  // thread limit, trading a little register-level reuse for much
  // higher thread-level parallelism / occupancy.
  int THREAD_TILE = 4;
  {
    int nt1 = TILE * TILE;
    int nt2 = (TILE / 2) * (TILE / 2);
    int nt4 = (TILE / 4) * (TILE / 4);
    const int kMaxThreadsPerBlock = 1024;
    if (nt1 <= kMaxThreadsPerBlock) {
      THREAD_TILE = 1;
    } else if (TILE % 2 == 0 && nt2 <= kMaxThreadsPerBlock) {
      THREAD_TILE = 2;
    } else if (TILE % 4 == 0 && nt4 <= kMaxThreadsPerBlock) {
      THREAD_TILE = 4;
    }
  }
  dim3 block((unsigned)((TILE / THREAD_TILE) * (TILE / THREAD_TILE)));
  dim3 grid(
      (unsigned)((Wout + TILE - 1) / TILE),
      (unsigned)((Hout + TILE - 1) / TILE),
      (unsigned)N
  );
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cudaError_t attr_err;
  if (THREAD_TILE == 1) {
    attr_err = cudaFuncSetAttribute(conv2d_tiled_kernel<1>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
        "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes,
        " (", cudaGetErrorString(attr_err), ")");
    conv2d_tiled_kernel<1><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)K, stride, padding,
        (int)Hout, (int)Wout,
        TILE, TILE, IH_tile, IW_tile, cout_tile
    );
  } else if (THREAD_TILE == 4) {
    attr_err = cudaFuncSetAttribute(conv2d_tiled_kernel<4>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
        "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes,
        " (", cudaGetErrorString(attr_err), ")");
    conv2d_tiled_kernel<4><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)K, stride, padding,
        (int)Hout, (int)Wout,
        TILE, TILE, IH_tile, IW_tile, cout_tile
    );
  } else {
    attr_err = cudaFuncSetAttribute(conv2d_tiled_kernel<2>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
        "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes,
        " (", cudaGetErrorString(attr_err), ")");
    conv2d_tiled_kernel<2><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)K, stride, padding,
        (int)Hout, (int)Wout,
        TILE, TILE, IH_tile, IW_tile, cout_tile
    );
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""
conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = conv2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv1.weight
        b = self.conv1.bias
        return self._ext.conv2d_forward(
            x.contiguous(),
            w.contiguous(),
            b.contiguous() if b is not None else None,
            int(self.conv1.stride[0]),
            int(self.conv1.padding[0]),
        )

