  }
  __syncthreads();
  int oh[THREAD_TILE];
  int ow[THREAD_TILE];
  #pragma unroll
  for (int i = 0; i < THREAD_TILE; ++i) { oh[i] = oh0 + i; ow[i] = ow0 + i; }
  bool active[THREAD_TILE][THREAD_TILE];
  bool any_active = false;
  #pragma unroll
  for (int i = 0; i < THREAD_TILE; ++i) {
    #pragma unroll
    for (int j = 0; j < THREAD_TILE; ++j) {
